// OperatorServiceServer is the server API for OperatorService service.
// All implementations must embed UnimplementedOperatorServiceServer
// for forward compatibility.
//
// OperatorService is the trusted local operator surface for Host policy, observation, and explicit
// destructive actions.
type OperatorServiceServer interface {
	// CreateMCPToken issues a token for the built-in MCP appliance.
	CreateMCPToken(context.Context, *CreateMCPTokenRequest) (*CreateMCPTokenResponse, error)
	// RotateMCPTokenKey starts an appliance update that replaces the MCP token signing key.
	RotateMCPTokenKey(context.Context, *RotateMCPTokenKeyRequest) (*RotateMCPTokenKeyResponse, error)
	// StartVM starts the shared VM with a whole-VM acknowledgement and the observed mutation fence.
	StartVM(context.Context, *StartVMRequest) (*StartVMResponse, error)
	// GetVM reads current VM state without inferring individual workload readiness.
	GetVM(context.Context, *GetVMRequest) (*GetVMResponse, error)
	// StopVM stops every workload in the shared VM under the supplied mutation fence.
	StopVM(context.Context, *StopVMRequest) (*StopVMResponse, error)
	// CreateAgentSession issues a revocable runtime session fixed to the selected environment.
	CreateAgentSession(context.Context, *CreateAgentSessionRequest) (*CreateAgentSessionResponse, error)
	// RevokeAgentSession revokes one runtime capability without deleting its environment or private
	// data.
	RevokeAgentSession(context.Context, *RevokeAgentSessionRequest) (*RevokeAgentSessionResponse, error)
	// ListAgentIntegrations reads local integration intent and configuration state for operator
	// review.
	ListAgentIntegrations(context.Context, *ListAgentIntegrationsRequest) (*ListAgentIntegrationsResponse, error)
	// PrepareAgentIntegration creates pending integration intent or reuses its existing environment
	// without changing that environment's policy.
	PrepareAgentIntegration(context.Context, *PrepareAgentIntegrationRequest) (*PrepareAgentIntegrationResponse, error)
	// CommitAgentIntegration commits the configuration fingerprint at the current integration
	// revision.
	CommitAgentIntegration(context.Context, *CommitAgentIntegrationRequest) (*CommitAgentIntegrationResponse, error)
	// BeginAgentIntegrationRemoval revokes access and records removal intent for the exact
	// integration.
	BeginAgentIntegrationRemoval(context.Context, *BeginAgentIntegrationRemovalRequest) (*BeginAgentIntegrationRemovalResponse, error)
	// CompleteAgentIntegrationRemoval completes the recorded integration removal after its owned
	// cleanup succeeds.
	CompleteAgentIntegrationRemoval(context.Context, *CompleteAgentIntegrationRemovalRequest) (*CompleteAgentIntegrationRemovalResponse, error)
	// ListAgentSessions reads session capability state separately from workload process state.
	ListAgentSessions(context.Context, *ListAgentSessionsRequest) (*ListAgentSessionsResponse, error)
	// RevokeAgentSessions revokes the selected integration's runtime sessions without discarding its
	// environment.
	RevokeAgentSessions(context.Context, *RevokeAgentSessionsRequest) (*RevokeAgentSessionsResponse, error)
	// GetSystemSnapshot reads operator inventory across Host-owned environments and registrations.
	GetSystemSnapshot(context.Context, *GetSystemSnapshotRequest) (*GetSystemSnapshotResponse, error)
	// GetSystemHealthSummary reads bounded Host and Guest health without enumerating workload
	// contents.
	GetSystemHealthSummary(context.Context, *GetSystemHealthSummaryRequest) (*GetSystemHealthSummaryResponse, error)
	// GetVMImpactSummary captures bounded owner references for a whole-VM decision, including
	// partial or overflowing observation state.
	GetVMImpactSummary(context.Context, *GetVMImpactSummaryRequest) (*GetVMImpactSummaryResponse, error)
	// ListEnvironments lists operator-visible environments with their logical ownership and
	// inventory freshness.
	ListEnvironments(context.Context, *ListEnvironmentsRequest) (*ListEnvironmentsResponse, error)
	// GetEnvironment reads environment policy and observed runtime facts under the caller's
	// authority.
	GetEnvironment(context.Context, *OperatorServiceGetEnvironmentRequest) (*OperatorServiceGetEnvironmentResponse, error)
	// ListEnvironmentImages reads logical image grants in the selected operator-visible environment.
	ListEnvironmentImages(context.Context, *ListEnvironmentImagesRequest) (*ListEnvironmentImagesResponse, error)
	// DeleteEnvironmentImage deletes one environment's image grant while preserving references owned
	// elsewhere.
	DeleteEnvironmentImage(context.Context, *DeleteEnvironmentImageRequest) (*DeleteEnvironmentImageResponse, error)
	// WatchEvents streams Host events for observation without granting mutation authority.
	WatchEvents(*WatchEventsRequest, grpc.ServerStreamingServer[WatchEventsResponse]) error
	// WatchMetrics streams sampled usage and freshness rather than reserved capacity.
	WatchMetrics(*WatchMetricsRequest, grpc.ServerStreamingServer[WatchMetricsResponse]) error
	// Logs reads bounded container output under the caller's environment authority.
	Logs(*OperatorServiceLogsRequest, grpc.ServerStreamingServer[OperatorServiceLogsResponse]) error
	// StopContainer stops the exact owned workload process under its current container fence.
	StopContainer(context.Context, *OperatorServiceStopContainerRequest) (*OperatorServiceStopContainerResponse, error)
	// ContinueContainer resumes Host desired-running intent for the selected operator-visible
	// container.
	ContinueContainer(context.Context, *ContinueContainerRequest) (*ContinueContainerResponse, error)
	// SignalContainer signals the retained workload process, whose natural exit can race the
	// request.
	SignalContainer(context.Context, *OperatorServiceSignalContainerRequest) (*OperatorServiceSignalContainerResponse, error)
	// DeleteContainer deletes an owned stopped container without deleting its named volumes.
	DeleteContainer(context.Context, *OperatorServiceDeleteContainerRequest) (*OperatorServiceDeleteContainerResponse, error)
	// UpdateEnvironmentPolicy changes the environment's approved PID, disk, and egress policy at its
	// current revision.
	UpdateEnvironmentPolicy(context.Context, *UpdateEnvironmentPolicyRequest) (*UpdateEnvironmentPolicyResponse, error)
	// PlanResetEnvironment reads a revision-bound cleanup plan that preserves named volumes.
	PlanResetEnvironment(context.Context, *PlanResetEnvironmentRequest) (*PlanResetEnvironmentResponse, error)
	// PlanDiscardEnvironment reads a revision-bound plan for deleting the environment's exact
	// private resources.
	PlanDiscardEnvironment(context.Context, *PlanDiscardEnvironmentRequest) (*PlanDiscardEnvironmentResponse, error)
	// ExecuteCleanup accepts the reviewed cleanup revision and exact volume confirmations before
	// Guest side effects.
	ExecuteCleanup(context.Context, *ExecuteCleanupRequest) (*ExecuteCleanupResponse, error)
	// PlanLocalDisposal freezes one local environment or exact registration for trusted operator
	// disposal.
	PlanLocalDisposal(context.Context, *PlanLocalDisposalRequest) (*PlanLocalDisposalResponse, error)
	// ExecuteLocalDisposal accepts confirmed local disposal and persists its replay fence before
	// resource deletion.
	ExecuteLocalDisposal(context.Context, *ExecuteLocalDisposalRequest) (*ExecuteLocalDisposalResponse, error)
	// GetOperation reads the stored result of the original Host operation.
	GetOperation(context.Context, *GetOperationRequest) (*GetOperationResponse, error)
	// RunDiagnostics collects bounded operator diagnostics with explicit sensitivity options.
	RunDiagnostics(context.Context, *RunDiagnosticsRequest) (*RunDiagnosticsResponse, error)
	// PreviewSupportBundle lists diagnostic content and sensitivity before support bundle export.
	PreviewSupportBundle(context.Context, *PreviewSupportBundleRequest) (*PreviewSupportBundleResponse, error)
	// ExportSupportBundle exports only the operator-approved diagnostic scope.
	ExportSupportBundle(context.Context, *ExportSupportBundleRequest) (*ExportSupportBundleResponse, error)
	// BeginRemoteEnrollment records one controller registration and its approved scope before
	// credential enrollment.
	BeginRemoteEnrollment(context.Context, *BeginRemoteEnrollmentRequest) (*BeginRemoteEnrollmentResponse, error)
	// ApplyManagedRemoteEnrollment applies a managed registration and one-time token within the
	// local enrollment owner.
	ApplyManagedRemoteEnrollment(context.Context, *ApplyManagedRemoteEnrollmentRequest) (*ApplyManagedRemoteEnrollmentResponse, error)
	// CompleteRemoteEnrollment commits credential completion for the current registration revision.
	CompleteRemoteEnrollment(context.Context, *CompleteRemoteEnrollmentRequest) (*CompleteRemoteEnrollmentResponse, error)
	// RetryRemoteEnrollment retries the existing incomplete registration under its current revision.
	RetryRemoteEnrollment(context.Context, *RetryRemoteEnrollmentRequest) (*RetryRemoteEnrollmentResponse, error)
	// BeginRemoteRevocation records revocation intent before stopping the registration's owned
	// workload authority.
	BeginRemoteRevocation(context.Context, *BeginRemoteRevocationRequest) (*BeginRemoteRevocationResponse, error)
	// CompleteRemoteRevocation completes the selected registration's durable revocation.
	CompleteRemoteRevocation(context.Context, *CompleteRemoteRevocationRequest) (*CompleteRemoteRevocationResponse, error)
	// UpdateRemotePool changes one registration's allocation policy without reallocating existing
	// workloads.
	UpdateRemotePool(context.Context, *UpdateRemotePoolRequest) (*UpdateRemotePoolResponse, error)
	// SetRemoteRegistrationState changes admission state independently of connector transport
	// connectivity.
	SetRemoteRegistrationState(context.Context, *SetRemoteRegistrationStateRequest) (*SetRemoteRegistrationStateResponse, error)
	// GetRemoteRegistration reads the selected registration, connector observation, and owned
	// allocations.
	GetRemoteRegistration(context.Context, *GetRemoteRegistrationRequest) (*GetRemoteRegistrationResponse, error)
	// SignRegistrationRecovery signs only the bounded single-use registration-recovery challenge
	// using the current device identity.
	SignRegistrationRecovery(context.Context, *SignRegistrationRecoveryRequest) (*SignRegistrationRecoveryResponse, error)
	// GetLocalDiskSummary reads Guest filesystem accounting without scanning every environment or
	// collecting compute metrics.
	GetLocalDiskSummary(context.Context, *GetLocalDiskSummaryRequest) (*GetLocalDiskSummaryResponse, error)
	// ListLocalEnvironmentPage reads an indexed bounded page of local environment summaries.
	ListLocalEnvironmentPage(context.Context, *ListLocalEnvironmentPageRequest) (*ListLocalEnvironmentPageResponse, error)
	// ListLocalRegistrationPage reads an indexed bounded page of local registration metadata.
	ListLocalRegistrationPage(context.Context, *ListLocalRegistrationPageRequest) (*ListLocalRegistrationPageResponse, error)
	// GetDeviceIdentity reads public device identity and custody state without exposing private key
	// bytes.
	GetDeviceIdentity(context.Context, *GetDeviceIdentityRequest) (*GetDeviceIdentityResponse, error)
	// ListPersonalMeshes reads the local projection of verified personal mesh state.
	ListPersonalMeshes(context.Context, *ListPersonalMeshesRequest) (*ListPersonalMeshesResponse, error)
	// CreatePersonalMesh creates personal mesh intent rooted in the current device identity.
	CreatePersonalMesh(context.Context, *CreatePersonalMeshRequest) (*CreatePersonalMeshResponse, error)
	// RevokePersonalMeshMember queues the signed removal of one member under the current mesh
	// revision.
	RevokePersonalMeshMember(context.Context, *RevokePersonalMeshMemberRequest) (*RevokePersonalMeshMemberResponse, error)
	// BeginPersonalMeshPairing creates a bounded pairing invitation without granting membership
	// before confirmation.
	BeginPersonalMeshPairing(context.Context, *BeginPersonalMeshPairingRequest) (*BeginPersonalMeshPairingResponse, error)
	// JoinPersonalMeshPairing joins the selected pairing exchange using its separate PAKE secret.
	JoinPersonalMeshPairing(context.Context, *JoinPersonalMeshPairingRequest) (*JoinPersonalMeshPairingResponse, error)
	// GetPersonalMeshPairing reads pairing progress and its confirmation state.
	GetPersonalMeshPairing(context.Context, *GetPersonalMeshPairingRequest) (*GetPersonalMeshPairingResponse, error)
	// ConfirmPersonalMeshPairing confirms the observed pairing identity before membership
	// publication.
	ConfirmPersonalMeshPairing(context.Context, *ConfirmPersonalMeshPairingRequest) (*ConfirmPersonalMeshPairingResponse, error)
	// RejectPersonalMeshPairing rejects the exact pairing exchange and its pending authority.
	RejectPersonalMeshPairing(context.Context, *RejectPersonalMeshPairingRequest) (*RejectPersonalMeshPairingResponse, error)
	// RepairDeviceIdentity replaces unavailable identity through explicit membership reset while
	// preserving the committed winner of concurrent repair.
	RepairDeviceIdentity(context.Context, *RepairDeviceIdentityRequest) (*RepairDeviceIdentityResponse, error)
	// CreateLocalServiceListener creates an operator-approved local listener for a current service
	// route.
	CreateLocalServiceListener(context.Context, *CreateLocalServiceListenerRequest) (*CreateLocalServiceListenerResponse, error)
	// ListServiceListeners reads active and revoked listener facts without reconstructing a live
	// listener after restart.
	ListServiceListeners(context.Context, *ListServiceListenersRequest) (*ListServiceListenersResponse, error)
	// RevokeServiceListener closes the exact listener and revokes its route authority.
	RevokeServiceListener(context.Context, *RevokeServiceListenerRequest) (*RevokeServiceListenerResponse, error)
	// CreateHostShare approves one checked Host directory for the selected environment.
	CreateHostShare(context.Context, *CreateHostShareRequest) (*CreateHostShareResponse, error)
	// RebindHostShare changes the checked source of an existing share under its revision fence.
	RebindHostShare(context.Context, *RebindHostShareRequest) (*RebindHostShareResponse, error)
	// RevokeHostShare revokes one share rather than granting general Host filesystem access.
	RevokeHostShare(context.Context, *RevokeHostShareRequest) (*RevokeHostShareResponse, error)
	// ListHostShares reads operator-approved directory shares and their current references.
	ListHostShares(context.Context, *ListHostSharesRequest) (*ListHostSharesResponse, error)
	mustEmbedUnimplementedOperatorServiceServer()
}

